const leads = $('Get Leads Requiring Follow-up').all();
const configs = $('Get Active Businesses').all();
const now = Date.now();
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function esc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const candidates = [];
for (const l of leads) {
  const j = l.json;
  const bid = String(j.business_id || '').trim();
  const cfgRow = configs.find(
    (c) => String(c.json.business_id || '').trim() === bid
  );
  if (!cfgRow) continue;
  const cj = cfgRow.json;

  // Business must be active.
  if (String(cj.active || '').trim().toLowerCase() !== 'true') continue;

  // Status must not be terminal.
  const status = String(j.status || '').trim().toLowerCase();
  if (['booked', 'lost', 'closed', 'no_response', 'failed'].indexOf(status) !== -1) continue;

  // followup_count < max_followups.
  const count = Number(j.followup_count || 0) || 0;
  const max = Number(cj.max_followups || 3) || 3;
  if (!(count < max)) continue;

  // next_followup_at must exist and be <= now.
  const rawNext = String(j.next_followup_at || '').trim();
  if (!rawNext) continue;
  const nextTs = new Date(rawNext).getTime();
  if (!isFinite(nextTs) || nextTs > now) continue;

  // Valid email required.
  const email = String(j.email || '').trim();
  if (!EMAIL_RE.test(email)) continue;

  candidates.push({
    json: Object.assign({}, j, {
      email: email,
      business_name: cj.business_name || '',
      owner_name: cj.owner_name || '',
      from_email: cj.from_email || '',
      reply_to_email: cj.reply_to_email || '',
      followup_delay_hours: Number(cj.followup_delay_hours || 24) || 24,
      max_followups: max,
      _esc_name: esc(j.name),
      _esc_business_name: esc(cj.business_name || ''),
      _esc_service: esc(j.service),
      _esc_booking_link: esc(j.booking_link),
      _noCandidates: false
    })
  });
}

if (candidates.length === 0) {
  return [{ json: { _noCandidates: true } }];
}
return candidates;

const candidates = $('Select Follow-up Candidates').all();

return $input.all().map((it, index) => {
  const j = it.json;

  // Prefer lead_id already present on the current item.
  // If the Email node stripped it, recover it from the
  // corresponding eligible-follow-up item.
  const source = candidates[index]?.json || {};
  const leadId = String(j.lead_id || source.lead_id || '').trim();

  if (!leadId) {
    throw new Error(
      `Missing lead_id in Advance Follow-up State. Item ${index + 1} has no lead_id.`
    );
  }

  const count = (Number(j.followup_count ?? source.followup_count ?? 0) || 0) + 1;
  const max = Number(j.max_followups ?? source.max_followups ?? 3) || 3;
  const delay = Number(j.followup_delay_hours ?? source.followup_delay_hours ?? 24) || 24;

  const nowIso = new Date().toISOString();
  const reachedMax = count >= max;

  return {
    json: {
      ...source,
      ...j,

      lead_id: leadId,
      followup_count: count,
      last_contact_at: nowIso,
      next_followup_at: reachedMax
        ? ''
        : new Date(Date.now() + delay * 3600 * 1000).toISOString(),
      status: reachedMax
        ? 'no_response'
        : String(j.status ?? source.status ?? 'new'),
      updated_at: nowIso
    }
  };
});

// F16 - WF05 failed follow-up sends used to dead-end at a noOp, so a
// persistently failing address was re-selected every hour forever and
// followup_count (which only ever counts SUCCESSFUL sends) never moved, making
// max_followups structurally unreachable. This node records the failure, counts
// total delivery failures in its own field, and retires the lead once the ceiling is
// reached. followup_count is deliberately NOT touched here: it stays a record of
// real contacts, so a transient SMTP failure cannot burn the customer's allowance.
const candidates = $('Select Follow-up Candidates').all();
const configs = $('Get Active Businesses').all();
const SECRET_RE = /(bearer)(\s+)([^,}"'`\s]+)|(secret|token|password|api[_ -]?key|authorization|bearer)((?:\\?["'])?\s*[:=]\s*)("(?:[^"\\]|\\.)*"|\\"(?:[^"\\]|\\.)*?\\"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`|bearer\s+[^,}"'`\s]+|[^,}"'`\s]+)/gi;
// Redacts a secret whatever delimiter or quoting surrounds it, so the shape a
// provider happens to emit cannot decide whether the value is reached. The value
// may be a double-quoted, single-quoted or backtick literal, a JSON-escaped
// double-quoted literal (which is what JSON.stringify hands the object branch),
// a `Bearer <credential>` pair, or a bare token. `redactSecret` re-emits the
// leading delimiter it found, quote and backslash included, so a redacted JSON
// payload stays well-formed and parseable instead of being cut in half. The
// leading branch still catches a bare "Bearer <credential>" with no keyword
// separator, and the value group may itself be "Bearer <credential>", so a
// header-style "Authorization: Bearer <jwt>" is consumed whole rather than
// leaving the JWT behind.
const redactSecret = (m, bearer, ws, token, keyword, sep, value) => {
  if (bearer) return bearer + ws + '[REDACTED]';
  const open = /^(\\?["'`])/.exec(value);
  const q = open ? open[1] : '';
  return keyword + sep + q + '[REDACTED]' + q;
};
function sanitize(v){
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v).replace(SECRET_RE, redactSecret);
  return String(v).replace(SECRET_RE, redactSecret);
}

return $input.all().map((it, index) => {
  const j = it.json;

  // The error item carries the candidate, but recover it the same defensive way
  // 'Advance Follow-up State' does so a stripped field cannot throw here.
  const source = candidates[index]?.json || {};

  const bid = String(j.business_id ?? source.business_id ?? '').trim();
  const lead = {
    lead_id: String(j.lead_id ?? source.lead_id ?? '').trim(),
    business_id: bid,
    status: String(j.status ?? source.status ?? ''),
    next_followup_at: String(j.next_followup_at ?? source.next_followup_at ?? ''),
    followup_fail_count: j.followup_fail_count ?? source.followup_fail_count ?? ''
  };
  if (!lead.lead_id) {
    throw new Error(
      `Missing lead_id in Build Failed Follow-up Record. Item ${index + 1} has no lead_id.`
    );
  }

  const cfg = configs.find((c) => String(c.json.business_id || '').trim() === bid);
  const config = cfg ? cfg.json : {};
  const max = Number(j.max_followups ?? source.max_followups ?? config.max_followups ?? 3) || 3;

  // Ceiling is a hard default, deliberately far above max_followups: a
  // temporary provider outage must not consume the customer's real follow-ups.
  const ceiling = Math.max(24, Number(config.max_followups || 3) * 4);

  // The field is absent on every pre-existing row, so it defaults on read.
  // WF01/WF03 are NOT changed: absent means 0.
  const nextFailCount = Number(lead.followup_fail_count || 0) + 1;
  const reachedCeiling = nextFailCount >= ceiling;
  const nowIso = new Date().toISOString();

  const rawErr = j.error !== undefined ? j.error : j._emailError;
  const msg =
    typeof rawErr === 'object' && rawErr !== null
      ? String(rawErr.message || JSON.stringify(rawErr))
      : String(rawErr || 'unknown follow-up email error');

  return {
    json: {
      lead_id: lead.lead_id,
      business_id: bid,
      followup_fail_count: nextFailCount,
      followup_fail_ceiling: ceiling,
      failed_attempts_remaining: Math.max(0, ceiling - nextFailCount),
      // Unchanged until the ceiling is reached, so the partial update is a
      // no-op for these two columns on an ordinary failure.
      status: reachedCeiling ? 'failed' : lead.status,
      next_followup_at: reachedCeiling ? '' : lead.next_followup_at,
      updated_at: nowIso,
      error_id: 'err_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      created_at: nowIso,
      workflow: '05 - Follow-up Sweeper',
      node: 'Send Follow-up Email',
      error_message: sanitize(
        'followup_email_failed (attempt ' + nextFailCount + '/' + ceiling + ', followup_count ' +
        String(j.followup_count ?? source.followup_count ?? 0) + '/' + max + '): ' + msg
      ).slice(0, 2000),
      execution_id: $execution.id,
      payload: sanitize({
        lead_id: lead.lead_id,
        business_id: bid,
        followup_count: Number(j.followup_count ?? source.followup_count ?? 0) || 0,
        max_followups: max,
        followup_fail_count: nextFailCount,
        followup_fail_ceiling: ceiling
      }).slice(0, 4000),
      resolved: false
    }
  };
});
